 "content": "def transform(grid):
    """Extend markers between two equal parallel line segments."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Extract straight, contiguous non-background runs, keeping their cells.
    runs = []
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == bg:
                c += 1
                continue
            color, start = grid[r][c], c
            while c < w and grid[r][c] == color:
                c += 1
            if c - start >= 2:
                runs.append((color, 'h', r, start, c - 1))
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            color, start = grid[r][c], r
            while r < h and grid[r][c] == color:
                r += 1
            if r - start >= 2:
                runs.append((color, 'v', c, start, r - 1))

    # Select the equal-length parallel rails with greatest separation.
    pairs = []
    for i, a in enumerate(runs):
        for b in runs[i+1:]:
            if a[0] != b[0] or a[1] != b[1]:
                continue
            if (a[4] - a[3]) != (b[4] - b[3]):
                continue
            # axis coordinate differs, while intervals on the long axis may shift
            if a[2] == b[2]:
                continue
            pairs.append((abs(a[2] - b[2]), a, b))
    if not pairs:
        return out
    _, a, b = max(pairs, key=lambda x: x[0])
    rail_color, orient = a[0], a[1]
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] != rail_color]

    # For each marker lying along one rail's span, send a ray to that rail,
    # and project its along-rail offset to the other rail with a connector.
    for r, c, color in markers:
        pos = c if orient == 'h' else r
        coord = r if orient == 'h' else c
        candidates = []
        for rail, other in ((a, b), (b, a)):
            lo, hi = rail[3], rail[4]
            if lo <= pos <= hi:
                candidates.append((rail, other))
        if not candidates:
            continue
        rail, other = min(candidates, key=lambda x: abs(coord - x[0][2]))
        out[r][c] = 4
        rail_coord, other_coord = rail[2], other[2]
        # Ray from source marker in the direction of its corresponding rail.
        step = 1 if rail_coord > coord else -1
        rr, cc = r, c
        while (rr if orient == 'h' else cc) != rail_coord:
            if orient == 'h':
                rr += step
            else:
                cc += step
            if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                out[rr][cc] = color
        # Matching offset projected onto the opposite rail; bridge the rails.
        offset = pos - rail[3]
        projected = other[3] + offset
        step2 = 1 if other_coord > rail_coord else -1
        line_coord = rail_coord + step2
        while line_coord != other_coord:
            if orient == 'h':
                if 0 <= projected < w and grid[line_coord][projected] == bg:
                    out[line_coord][projected] = color
            else:
                if 0 <= line_coord < h and grid[projected][line_coord] == bg:
                    out[projected][line_coord] = color
            line_coord += step2
    return out

